def compute(vars):
    revenue_2018 = vars["v1"]
    revenue_2019 = vars["v2"]
    average_revenue = (revenue_2018 + revenue_2019) / 2

    return {
        "value": average_revenue,
        "trace": {
            "revenue_2018": revenue_2018,
            "revenue_2019": revenue_2019,
            "average_revenue": average_revenue,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
